// Package db owns the Postgres pool, embedded migrations and transactions.
// Queries are generated by sqlc into internal/db/sqlc (see sqlc.yaml).
package db

import (
	"context"
	"embed"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"strings"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"

	"github.com/calaba/calaba/server/internal/db/sqlc"
)

//go:embed migrations/*.sql
var migrationsFS embed.FS

// uuidv7SQL creates public.uuidv7() for PostgreSQL < 18, see ensureUUIDv7.
//
//go:embed uuidv7.sql
var uuidv7SQL string

// uuidv7LockID is the pg_advisory_xact_lock key of ensureUUIDv7 ("calabau7"), not goose's key.
const uuidv7LockID int64 = 0x63616c6162617537

// DB bundles the pool and the sqlc queries bound to it.
type DB struct {
	Pool *pgxpool.Pool
	Q    *sqlc.Queries
}

// Connect opens a pool and pings it.
func Connect(ctx context.Context, url string) (*DB, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("db: parse url: %w", err)
	}
	// pgx's default (max(4, NumCPU)) is too small for IDENTIFY storms after a deploy
	// (review L16). ?pool_max_conns=N in DATABASE_URL overrides this.
	if !strings.Contains(url, "pool_max_conns") {
		cfg.MaxConns = 20
	}
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("db: connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("db: ping: %w", err)
	}
	return &DB{Pool: pool, Q: sqlc.New(pool)}, nil
}

// Close closes the pool.
func (d *DB) Close() { d.Pool.Close() }

// Tx runs fn in a transaction; it commits when fn returns nil and rolls back otherwise.
func (d *DB) Tx(ctx context.Context, fn func(q *sqlc.Queries) error) error {
	return d.TxRaw(ctx, func(q *sqlc.Queries, _ pgx.Tx) error { return fn(q) })
}

// ReadTx runs fn in a READ ONLY transaction (dynamic reads that need SET LOCAL, e.g. search
// with its statement timeout). The database rejects any write in it, so it needs no admission.
func (d *DB) ReadTx(ctx context.Context, fn func(tx pgx.Tx) error) error {
	return pgx.BeginTxFunc(ctx, d.Pool, pgx.TxOptions{AccessMode: pgx.ReadOnly}, fn)
}

func newProvider(d *DB) (*goose.Provider, error) {
	sub, err := fs.Sub(migrationsFS, "migrations")
	if err != nil {
		return nil, err
	}
	// Session-level pg_advisory_lock: with several replicas only one migrates, others wait.
	locker, err := lock.NewPostgresSessionLocker()
	if err != nil {
		return nil, err
	}
	return goose.NewProvider(goose.DialectPostgres, stdlib.OpenDBFromPool(d.Pool), sub,
		goose.WithSessionLocker(locker))
}

// ensureUUIDv7 makes uuidv7() callable before the migrations run: the id DEFAULTs and some
// queries call it, and it is built in only since PostgreSQL 18 (ADR-0037). On 17 it creates
// public.uuidv7() (uuidv7.sql: the layout and ordering of the built-in) once per database.
// On 18 nothing is created: the built-in lives in pg_catalog, which is searched first, so it
// resolves even next to a public.uuidv7() kept from an upgrade (the DEFAULTs bound to that one
// keep working). A database where uuidv7() resolves is never changed. Reports whether it
// created the function.
func (d *DB) ensureUUIDv7(ctx context.Context) (bool, error) {
	// Reads pg_proc rather than only resolving the name: opening the catalog applies the pending
	// cache invalidations, so a replica that waited for the lock below sees the function created
	// meanwhile by another one (a bare to_regprocedure() would answer from its stale cache). Read
	// committed, so that the check after the lock takes a new snapshot.
	const exists = `SELECT EXISTS (SELECT FROM pg_catalog.pg_proc WHERE oid = to_regprocedure('uuidv7()'))`
	var ok bool
	if err := d.Pool.QueryRow(ctx, exists).Scan(&ok); err != nil {
		return false, fmt.Errorf("uuidv7: %w", err)
	}
	if ok {
		return false, nil
	}
	var version string
	err := pgx.BeginTxFunc(ctx, d.Pool, pgx.TxOptions{IsoLevel: pgx.ReadCommitted}, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, `SELECT pg_advisory_xact_lock($1)`, uuidv7LockID); err != nil {
			return err
		}
		if err := tx.QueryRow(ctx, exists).Scan(&ok); err != nil || ok {
			return err
		}
		if _, err := tx.Exec(ctx, uuidv7SQL); err != nil {
			return err
		}
		return tx.QueryRow(ctx, `SELECT current_setting('server_version')`).Scan(&version)
	})
	if err != nil {
		return false, fmt.Errorf("uuidv7: create public.uuidv7(): %w", err)
	}
	if ok {
		return false, nil
	}
	slog.Info("created public.uuidv7(): no built-in uuidv7() before PostgreSQL 18", "server_version", version)
	return true, nil
}

// Migrate applies all pending migrations under an advisory lock.
func (d *DB) Migrate(ctx context.Context) error {
	if _, err := d.ensureUUIDv7(ctx); err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	p, err := newProvider(d)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	res, err := p.Up(ctx)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	for _, r := range res {
		slog.Info("migration applied", "version", r.Source.Version, "file", r.Source.Path, "dur", r.Duration)
	}
	return nil
}

// MigrateTo applies pending migrations up to and including version (data-migration tests).
func (d *DB) MigrateTo(ctx context.Context, version int64) error {
	if _, err := d.ensureUUIDv7(ctx); err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	p, err := newProvider(d)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	if _, err := p.UpTo(ctx, version); err != nil {
		return fmt.Errorf("migrate to %d: %w", version, err)
	}
	return nil
}

// MigrationStatus returns "version applied|pending" lines.
func (d *DB) MigrationStatus(ctx context.Context) ([]string, error) {
	p, err := newProvider(d)
	if err != nil {
		return nil, err
	}
	st, err := p.Status(ctx)
	if err != nil {
		return nil, err
	}
	out := make([]string, 0, len(st))
	for _, s := range st {
		out = append(out, fmt.Sprintf("%05d %-8s %s", s.Source.Version, s.State, s.Source.Path))
	}
	return out, nil
}

// IsNotFound reports whether err is "no rows".
func IsNotFound(err error) bool { return errors.Is(err, pgx.ErrNoRows) }

// UniqueViolation returns the violated constraint name, or "" if err is not a unique violation.
func UniqueViolation(err error) string {
	var pe *pgconn.PgError
	if errors.As(err, &pe) && pe.Code == "23505" {
		return pe.ConstraintName
	}
	return ""
}

// IsForeignKeyViolation reports a 23503 error.
func IsForeignKeyViolation(err error) bool {
	var pe *pgconn.PgError
	return errors.As(err, &pe) && pe.Code == "23503"
}
